// RSS/Atom/RDF in dasselbe Format bringen wie die Tavily-Ergebnisse.

const KEYWORDS = [
  'payment', 'payments', 'instant payment', 'digital euro', 'sepa',
  'card', 'retail payment', 'settlement', 'tips', 'target',
  'psd2', 'psd3', 'psr', 'stablecoin', 'tokenis', 'tokeniz', 'fraud'
];

function toArray(x) {
  if (x === undefined || x === null) return [];
  return Array.isArray(x) ? x : [x];
}

// xml2js legt Textinhalte teils unter "_" ab, Attribute unter "$"
function text(v) {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'object') {
    if (typeof v._ === 'string') return v._.trim();
    if (v.$ && typeof v.$.href === 'string') return v.$.href.trim();
  }
  return '';
}

function findItems(root) {
  if (root?.rss?.channel?.item) return toArray(root.rss.channel.item);
  if (root?.feed?.entry) return toArray(root.feed.entry);
  const rdf = root?.['rdf:RDF'] || root?.RDF;
  if (rdf?.item) return toArray(rdf.item);
  if (root?.channel?.item) return toArray(root.channel.item);
  return [];
}

const out = [];

for (const input of $input.all()) {
  const meta = $('Feed List').all()
    .map(i => i.json)
    .find(f => true); // Fallback, falls Zuordnung fehlschlaegt

  const root = input.json.data || input.json;
  const items = findItems(root);

  for (const it of items.slice(0, 25)) {   // max. 25 Eintraege pro Feed
    const title = text(it.title);
    const link = text(it.link) || text(it.guid) || text(it.id);
    const desc = text(it.description) || text(it.summary) || text(it.content);
    const date = text(it.pubDate) || text(it['dc:date']) || text(it.published) || text(it.updated);

    if (!title || !link) continue;

    // Themenfilter: RSS liefert ALLES, wir wollen nur Payments-Relevantes
    const haystack = (title + ' ' + desc).toLowerCase();
    const matched = KEYWORDS.filter(k => haystack.includes(k));
    if (matched.length === 0) continue;

    out.push({
      json: {
        title: title,
        url: link,
        content: desc || title,
        contentIsTitleOnly: !desc,
        published_date: date || null,
        origin: 'rss',
        matchedKeywords: matched
      }
    });
  }
}

return out;

// Liste der Primaerquellen-Feeds.
// Jeder Eintrag wird ein eigenes n8n-Item -> der HTTP-Node laeuft pro Item einmal.

const feeds = [
  { feedUrl: 'https://www.ecb.europa.eu/rss/press.html', sourceName: 'ECB Press', tier: 1 },
  { feedUrl: 'https://www.ecb.europa.eu/rss/blog.html',  sourceName: 'ECB Blog',  tier: 1 }
];

return feeds.map(f => ({ json: f }));

// Tavily-Ergebnisse in dieselbe flache Struktur bringen wie die RSS-Items.

const raw = $input.first().json;
const results = Array.isArray(raw.results) ? raw.results : [];

if (results.length === 0) {
  // Leeres Ergebnis: ein Platzhalter-Item, damit der Merge-Node nicht haengt
  return [{ json: { origin: 'tavily', empty: true } }];
}

return results.map(r => ({
  json: {
    title: String(r.title || '').trim(),
    url: String(r.url || '').trim(),
    content: String(r.content || '').trim(),
    published_date: r.published_date || null,
    relevance_score: typeof r.score === 'number' ? r.score : 0,
    origin: 'tavily',
    contentIsTitleOnly: false
  }
}));

// KI-Analyse mit einem ueberpruefbaren Quellenanhang kombinieren.

const ctx = $('Clean and Rank Sources').first().json;
const llm = $('Analyse and Draft Brief').first().json;

const analysis = String(llm.text || llm.response || '').trim();

// Modellseitige Vollverweigerung erkennen. Vertrag (Analyse-Prompt, Regel 4):
// die Antwort besteht dann NUR aus dem Grossbuchstaben-Marker am Anfang.
const model_refused = /^INSUFFICIENT EVIDENCE\b/.test(analysis);

// Strukturierte Metadaten aus dem Haiku-Zweig
let meta = {};
try {
  const rawMeta = $('Extract Metadata').first().json;
  meta = rawMeta.output || rawMeta;
} catch (e) {
  meta = { extraction_error: String(e) };
}

const now = new Date();
const dateStr = now.toISOString().slice(0, 10);

const header = [
  `# Payments Intelligence Brief`,
  ``,
  `**Topic:** ${ctx.topic}`,
  `**Generated:** ${dateStr}`,
  `**Evidence window:** last ${ctx.timeframe}`,
  `**Sources analysed:** ${ctx.sourceCount} (${ctx.tier1Count} regulator/official, ${ctx.tier2Count} company primary)`,
  ``,
  `---`,
  ``
].join('\n');

const appendix = [
  ``,
  `---`,
  ``,
  `## Sources`,
  ``,
  ctx.sourceList,
  ``,
  `---`,
  ``,
  `*Generated automatically. All factual claims carry [S#] markers referring to the numbered sources above. Analytical judgements are the model's interpretation and are not sourced.*`
].join('\n');

const brief = header + analysis + appendix;

return [{
  json: {
    topic: ctx.topic,
    timeframe: ctx.timeframe,
    run_started_at: ctx.runStartedAt,
    generated_at: now.toISOString(),
    source_count: ctx.sourceCount,
    tier1_count: ctx.tier1Count,
    tier2_count: ctx.tier2Count,
    had_enough_evidence: ctx.hasEnoughEvidence,
    model_refused: model_refused,
    brief_markdown: brief,
    sources: ctx.sources,
    metadata: meta
  }
}];

// Quellen aus allen Kanaelen normalisieren, filtern, deduplizieren, ranken.

const prep = $('Build Search Query').first().json;
// Rohquellen aus dem Merge holen (Triage liefert nur Scores, keine Quellen)
const rawSources = $('Combine Sources').all().map(i => i.json).filter(x => !x.empty);

// Triage-Scores anwenden
const MIN_RELEVANCE = 25;
let triageDropped = 0;
let incoming = rawSources;

try {
  const t = $('Triage Relevance').first().json;
  const scores = (t.output || t).scores || [];
  const scoreMap = {};
  for (const s of scores) scoreMap[s.index] = s.score;

  incoming = rawSources.filter((src, i) => {
    const sc = typeof scoreMap[i] === 'number' ? scoreMap[i] : 100;
    if (sc < MIN_RELEVANCE) { triageDropped++; return false; }
    src.triage_score = sc;
    return true;
  });
} catch (e) {
  // Triage fehlgeschlagen: lieber alle Quellen behalten als gar keine
  incoming = rawSources;
}

// ---- Harte Sperre: nie in die Evidenz ----------------------------------
// Zweite Verteidigungslinie. Suchmaschinen-Parameter sind Wuensche,
// keine Garantien. Snippets von Plattformen mit nutzergenerierten
// Inhalten enthalten unkontrollierbare Kommentarspalten.
const NEVER_USE = [
  'instagram.com', 'facebook.com', 'x.com', 'twitter.com', 'threads.net',
  'tiktok.com', 'reddit.com', 'quora.com', 'youtube.com', 'pinterest.com',
  'bsky.app', 'mastodon.social', '4chan.org', 'telegram.me', 't.me'
];

// ---- Quellen-Qualitaetsstufen ------------------------------------------
const TIER_1 = [
  'ecb.europa.eu', 'eba.europa.eu', 'europa.eu', 'bis.org',
  'bankingsupervision.europa.eu', 'esrb.europa.eu',
  'bankofengland.co.uk', 'federalreserve.gov', 'bundesbank.de',
  'sec.gov', 'esma.europa.eu'
];
const TIER_2 = [
  'adyen.com', 'stripe.com', 'visa.com', 'mastercard.com', 'paypal.com',
  'klarna.com', 'revolut.com', 'checkout.com', 'worldline.com',
  'nexigroup.com', 'fiserv.com', 'globalpayments.com', 'block.xyz',
  'shift4.com', 'apple.com', 'google.com'
];
const TIER_3 = [
  'reuters.com', 'ft.com', 'bloomberg.com', 'wsj.com', 'cnbc.com',
  'forbes.com', 'economist.com', 'handelsblatt.com',
  'finextra.com', 'thepaypers.com', 'paymentsdive.com', 'pymnts.com',
  'fintechfutures.com', 'thefintechtimes.com', 'fintechmagazine.com',
  'centralbanking.com', 'americanbanker.com', 'bankingdive.com',
  'techcrunch.com', 'theverge.com'
];

function domainOf(url) {
  const m = String(url).match(/^https?:\/\/([^\/?#:]+)/i);
  if (!m) return '';
  return m[1].replace(/^www\./i, '').toLowerCase();
}

function tierOf(domain) {
  if (TIER_1.some(d => domain.endsWith(d))) return 1;
  if (TIER_2.some(d => domain.endsWith(d))) return 2;
  if (TIER_3.some(d => domain.endsWith(d))) return 3;
  return 4;
}

// ---- Themenbezug pruefen (nur fuer RSS noetig) ---------------------------
const topicWords = String(prep.topic || '')
  .toLowerCase()
  .split(/\s+/)
  .filter(w => w.length > 3);

function matchesTopic(item) {
  if (item.origin !== 'rss') return true;      // Tavily ist bereits gefiltert
  if (topicWords.length === 0) return true;
  const hay = (item.title + ' ' + item.content).toLowerCase();
  return topicWords.some(w => hay.includes(w));
}

// ---- Normalisieren, filtern, deduplizieren ------------------------------
const seenUrls = new Set();
const seenTitles = new Set();
const seenContent = new Set();
const cleaned = [];
let dropped = 0;

for (const r of incoming) {
  const url = String(r.url || '').trim();
  const title = String(r.title || '').trim();
  if (!url || !title) { dropped++; continue; }

  if (!matchesTopic(r)) { dropped++; continue; }

  const domain = domainOf(url);

  // Harte Sperre zuerst
  if (NEVER_USE.some(d => domain.endsWith(d))) { dropped++; continue; }

  // Kanonische URL: Tracking-Parameter, Anker, doppelte Slashes entfernen
  const canonical = url
    .split('#')[0]
    .split('?')[0]
    .replace(/([^:])\/\//g, '$1/')
    .replace(/\/$/, '')
    .toLowerCase();
  if (seenUrls.has(canonical)) { dropped++; continue; }
    // Index-, Übersichts- und Marketingseiten ohne Nachrichteninhalt
   if (/\/(resource-filter|all-payments-news)\/?$/i.test(canonical)) {
    dropped++; continue;
  }

  const titleKey = title.toLowerCase().replace(/[^a-z0-9 ]/g, '').slice(0, 60);
  if (titleKey && seenTitles.has(titleKey)) { dropped++; continue; }

  let content = String(r.content || '').replace(/\s+/g, ' ').trim();
  const titleOnly = r.contentIsTitleOnly === true || content === title;

  // Near-Duplicate: gleicher Textanfang trotz anderer Ueberschrift
  // (z.B. Agenturmeldung bei AOL und Yahoo Finance)
  const contentKey = content.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 200);
  if (contentKey.length > 100) {
    if (seenContent.has(contentKey)) { dropped++; continue; }
    seenContent.add(contentKey);
  }

  // Volltext-Quellen muessen substanziell sein; Headline-Only nicht
  if (!titleOnly && content.length < 120) { dropped++; continue; }

  if (!titleOnly) {
    // Boilerplate: typische Footer- und Navigationsphrasen
    const boilerplatePatterns = [
      /is part of the .{0,40}Division of/i,
      /registered office is/i,
      /all copyright resides with them/i,
      /this site is operated by a business/i,
      /cookie|privacy policy|terms of use/i,
      /subscribe to (our|the) newsletter/i
    ];
    const imagePlaceholders = (content.match(/Image \d+:/g) || []).length;
    const boilerplateHits = boilerplatePatterns.filter(p => p.test(content)).length;
    if (boilerplateHits >= 2 || imagePlaceholders >= 3) { dropped++; continue; }

    // Strukturtest: echter Fliesstext hat Saetze, Navigationslisten nicht
    const words = content.split(/\s+/).length;
    const sentenceEnds = (content.match(/[.!?]\s/g) || []).length;
    const wordsPerSentence = sentenceEnds > 0 ? words / sentenceEnds : words;
    if (words > 40 && wordsPerSentence > 60) { dropped++; continue; }

    // Index-/Uebersichtsseiten: viele abgeschnittene Fragmente
    const fragments = (content.match(/\[\.\.\.\]/g) || []).length;
    if (fragments >= 3) { dropped++; continue; }
  }

  content = content.slice(0, 1200);

  const tier = tierOf(domain);

  seenUrls.add(canonical);
  if (titleKey) seenTitles.add(titleKey);

  cleaned.push({
    title, url, canonical, domain, tier,
    published_date: r.published_date || null,
    relevance_score: typeof r.relevance_score === 'number' ? r.relevance_score : 0,
    origin: r.origin || 'unknown',
    titleOnly,
    content
  });
}

// ---- Ranking: Quellenqualitaet vor Suchrelevanz --------------------------
cleaned.sort((a, b) => (a.tier - b.tier) || (b.relevance_score - a.relevance_score));

const selected = cleaned.slice(0, 10);   // KOSTENBREMSE

// ---- Evidenzblock -------------------------------------------------------
const evidence = selected.map((s, i) => {
  const note = s.titleOnly
    ? ' [HEADLINE ONLY — full article text was not retrieved]'
    : '';
  return [
    `[S${i + 1}]`,
    `Title: ${s.title}`,
    `Source: ${s.domain} (quality tier ${s.tier}, via ${s.origin})${note}`,
    `Published: ${s.published_date || 'unknown'}`,
    `URL: ${s.url}`,
    `Excerpt: ${s.content}`
  ].join('\n');
}).join('\n\n---\n\n');

const sourceList = selected.map((s, i) =>
  `[S${i + 1}] ${s.title} — ${s.domain} — ${s.url}`
).join('\n');

return [{
  json: {
    topic: prep.topic,
    timeframe: prep.timeframe,
    sourceCount: selected.length,
    droppedCount: dropped,
    triageDroppedCount: triageDropped,
    tier1Count: selected.filter(s => s.tier === 1).length,
    tier2Count: selected.filter(s => s.tier === 2).length,
    rssCount: selected.filter(s => s.origin === 'rss').length,
    hasEnoughEvidence: selected.length >= 3,
    evidence,
    sourceList,
    sources: selected,
    runStartedAt: prep.runStartedAt
  }
}];

// Wandelt das Nutzer-Thema in eine Payments-Suchanfrage um
// und setzt die Kosten-/Umfangsgrenzen für diesen Lauf.

const input = $input.first().json;

const topic = String(input.topic || '').trim();
const timeframe = String(input.timeframe || 'month').trim();

if (!topic) {
  throw new Error('Kein Thema uebergeben. Pruefe, ob das Formularfeld "topic" heisst.');
}

// Eingabe-Validierung: kuerzen und Zeichen entfernen, die JSON zerstoeren
const safeTopic = topic.replace(/["\\\n\r]/g, ' ').slice(0, 120);

// Kontextbegriffe lenken die Suchmaschine in Richtung Payments-Berichterstattung
const contextTerms = 'payments fintech acquiring issuing card network merchant';

const query = `${safeTopic} ${contextTerms} news announcement`;

// Quellen, die die KI nie lesen soll
const excludeDomains = [
  'reddit.com', 'quora.com', 'medium.com', 'substack.com',
  'linkedin.com', 'facebook.com', 'instagram.com', 'threads.net',
  'x.com', 'twitter.com', 'youtube.com', 'tiktok.com',
  'pinterest.com', 'bsky.app', 'mastodon.social',
  'aol.co.uk', 'aol.com', 'msn.com'
];

return [{
  json: {
    topic: safeTopic,
    timeframe: timeframe,
    query: query,
    maxResults: 8,
    excludeDomains: excludeDomains,
    runStartedAt: new Date().toISOString()
  }
}];

// Kompaktes Ergebnis fuer den aufrufenden Monitor-Workflow.

const prep = $('Prepare DB Record').first().json;

// Uebersprungen wegen zu schwacher Quellenlage?
if (prep.skipped === true) {
  return [{
    json: {
      topic: prep.topic,
      was_new: false,
      skipped: true,
      skip_reason: prep.skip_reason,
      sources_written: 0,
      finished_at: new Date().toISOString()
    }
  }];
}

let briefRow = {};
try {
  briefRow = $('Insert Brief').first().json || {};
} catch (e) {
  briefRow = {};
}

let sourcesWritten = 0;
try {
  sourcesWritten = $('Insert Sources').all().filter(i => i.json && i.json.id).length;
} catch (e) {
  sourcesWritten = 0;
}

return [{
  json: {
    topic: prep.topic,
    content_hash: prep.content_hash,
    brief_id: briefRow.id || null,
    was_new: briefRow.was_inserted === true,
    skipped: false,
    sources_written: sourcesWritten,
    source_count: prep.source_count,
    tier1_count: prep.tier1_count,
    impact_score: prep.impact_score,
    confidence_score: prep.confidence_score,
    headline: prep.headline,
    finished_at: new Date().toISOString()
  }
}];
